const DB='furusatoStandaloneDB', DOCS='documents', LOGS='logs', META='meta';
const $=id=>document.getElementById(id);
let state={documents:[],logs:[],manual:{}};
let activeYear=2026;
const yen=n=>n==null||!Number.isFinite(Number(n))?'—':Math.round(Number(n)).toLocaleString('ja-JP')+'円';
const num=v=>{const n=Number(String(v??'').replace(/,/g,''));return Number.isFinite(n)?n:0};
function addLog(msg,obj={}){const e={time:new Date().toISOString(),msg,...obj};state.logs.push(e);return e}
function openDB(){return new Promise((res,rej)=>{const r=indexedDB.open(DB,3);r.onupgradeneeded=()=>{const db=r.result;if(!db.objectStoreNames.contains(DOCS))db.createObjectStore(DOCS,{keyPath:'id'});if(!db.objectStoreNames.contains(LOGS))db.createObjectStore(LOGS,{keyPath:'id',autoIncrement:true});if(!db.objectStoreNames.contains(META))db.createObjectStore(META,{keyPath:'key'});};r.onsuccess=()=>res(r.result);r.onerror=()=>rej(r.error)})}
async function tx(store,mode,fn){const db=await openDB();return new Promise((res,rej)=>{const t=db.transaction(store,mode),s=t.objectStore(store);let out;try{out=fn(s)}catch(e){rej(e);return}t.oncomplete=()=>res(out);t.onerror=()=>rej(t.error)})}
const putDoc=d=>tx(DOCS,'readwrite',s=>s.put(d));
const allDocs=()=>tx(DOCS,'readonly',s=>new Promise((res,rej)=>{const r=s.getAll();r.onsuccess=()=>res(r.result);r.onerror=()=>rej(r.error)}));
const putLog=e=>tx(LOGS,'readwrite',s=>s.add(e));
const allLogs=()=>tx(LOGS,'readonly',s=>new Promise((res,rej)=>{const r=s.getAll();r.onsuccess=()=>res(r.result);r.onerror=()=>rej(r.error)}));
const getMeta=k=>tx(META,'readonly',s=>new Promise((res,rej)=>{const r=s.get(k);r.onsuccess=()=>res(r.result?.value);r.onerror=()=>rej(r.error)}));
const putMeta=(key,value)=>tx(META,'readwrite',s=>s.put({key,value}));
function inferKind(d){
 const text=[d.kind,d.type,d.name,d.document,d.source,d.fileName,d.filename].filter(Boolean).join(' ').toLowerCase();
 if(/gense[nb]|源泉|withholding/.test(text)) return 'withholding';
 if(/bonus|賞与/.test(text)) return 'bonus';
 if(/chinginmeisai|給与|賃金|payment\s*slip|salary/.test(text)) return 'salary';
 if(d.bonusAmount!=null||d.standardBonusAmounts||d.decreeAmount!=null) return 'bonus';
 if(d.taxableAmount!=null||d.paymentItems||d.deductionItems||d.baseSalaryBreakdown||d.workingRecord) return 'salary';
 return d.kind||d.type||'unknown';
}
function canonicalId(d){return `${d.year||0}-${d.kind||'unknown'}-${d.month??'annual'}-${String(d.document||d.name||d.source||'document').replace(/[^0-9A-Za-z_-]+/g,'_')}`}
function makeId(d){return canonicalId(d)}
function mapNested(d){
 const p=d.paymentItems||{}, q=d.deductionItems||{}, a=d.additionalPaymentItems||{}, w=d.workingRecord||{}, b=d.baseSalaryBreakdown||{}, sm=d.standardMonthlyRemuneration||{}, sb=d.standardBonusAmounts||{};
 const get=(obj,...keys)=>{for(const k of keys)if(obj[k]!=null)return obj[k];return null};
 const health=get(q,'健康保険料（基本','健康保険料（基本）'), healthSpecial=get(q,'健康保険料（特定','健康保険料（特定）');
 const out={...d}; out.kind=inferKind(out); out.name=out.name||out.document||`${out.year||''}-${out.month||''}`; out.payDate=out.payDate||out.payday||out.date||null; out.year=Number(out.year||String(out.payDate||'').slice(0,4)||0); out.month=out.month==null?null:Number(out.month);
 if(out.kind==='salary'){
  out.totalPayment=out.totalPayment??null; out.taxable=out.taxable??out.taxableAmount??null; out.nonTaxable=out.nonTaxable??out.nonTaxableAmount??null; out.additional=out.additional??out.additionalPaymentTotal??null; out.net=out.net??out.netPayment??null;
  out.employment=out.employment??get(q,'雇用保険料'); out.health=out.health??health; out.healthSpecial=out.healthSpecial??healthSpecial; out.care=out.care??get(q,'介護保険料'); out.pension=out.pension??get(q,'年金保険料'); out.incomeTax=out.incomeTax??get(q,'所得税'); out.residentTax=out.residentTax??get(q,'住民税');
  out.childSupport=out.childSupport??get(q,'子ども・子育て支援金'); out.deductions=out.deductions??out.totalDeduction; out.paymentItems=p; out.deductionItems=q; out.additionalPaymentItems=a; out.workingRecord=w; out.baseSalaryBreakdown=b; out.standardMonthlyRemuneration=sm;
 } else if(out.kind==='bonus'){
  out.amount=out.amount??out.bonusAmount??out.totalPayment??null; out.taxable=out.taxable??out.taxableGross??out.amount; out.totalPayment=out.totalPayment??out.amount; out.net=out.net??out.netPayment??null; out.employment=out.employment??get(q,'雇用保険料'); out.health=out.health??get(q,'健康保険料（基本','健康保険料（基本）'); out.healthSpecial=out.healthSpecial??get(q,'健康保険料（特定','健康保険料（特定）'); out.care=out.care??get(q,'介護保険料'); out.pension=out.pension??get(q,'年金保険料'); out.childSupport=out.childSupport??get(q,'子ども・子育て支援金'); out.incomeTax=out.incomeTax??get(q,'所得税'); out.deductions=out.deductions??out.totalDeduction; out.paymentItems=p; out.deductionItems=q; out.standardBonusAmounts=sb;
 }
 return out;
}
function normalizeDoc(raw,sourceName){
 const d=mapNested({...raw}); d.kind=inferKind(d); d.id=makeId(d); d.source=d.source||sourceName||'structured-json'; d.status=d.status||'parsed';
 d.social=d.social==null?deriveSocial(d):num(d.social);
 if(d.kind==='salary'){
   d.missingFields=[];
   if(d.year<=0)d.missingFields.push('year');
   if(d.month==null)d.missingFields.push('month');
   if(d.taxable==null)d.missingFields.push('taxableAmount');
   // A salary slip can be used for the annual limit calculation with the
   // taxable amount alone. totalPayment/nonTaxable/additional/tax/resident
   // are readout-detail fields, not calculation blockers. In particular,
   // the verified 2025/12 record has taxable=804,000 and social=96,931 but
   // those optional fields are unavailable in the structured import.
   // Do not turn that into a false "確認必要" state.
   d.needsReview=d.missingFields.length>0;
 }else{
   d.missingFields=[];
   d.needsReview=false;
 }
 return d;
}
function deriveSocial(d){return ['employment','health','healthSpecial','care','childSupport','pension'].map(k=>num(d[k])).reduce((a,b)=>a+b,0)}
async function importJsonText(text,sourceName='ChatGPT JSON'){
 const parsed=JSON.parse(text); const list=Array.isArray(parsed)?parsed:(Array.isArray(parsed.documents)?parsed.documents:[]); if(!list.length)throw new Error('documents配列がありません');
 let added=0,updated=0; for(const raw of list){const d=normalizeDoc(raw,sourceName);const old=state.documents.find(x=>x.id===d.id);await putDoc(d);old?updated++:added++}
 const log=addLog('データ反映',{source:sourceName,count:list.length,added,updated});await putLog(log);state.documents=await allDocs();state.logs=await allLogs();render();showMessage(`反映完了：${added}件追加、${updated}件更新。DB保存済み`,'ok');
}
function lifeDeduction(premium,type,year,under23=false){const x=num(premium);if(!x)return 0;if(type==='newLife'&&year>=2026&&under23)return x<=30000?x:x<=60000?x/2+15000:x<=120000?x/4+30000:60000;if(type==='new'||type==='newLife')return x<=20000?x:x<=40000?x/2+10000:x<=80000?x/4+20000:40000;if(type==='old')return x<=25000?x:x<=50000?x/2+12500:x<=100000?x/4+25000:50000;return 0}
function calcLife(m,year){const under23=Boolean(m.under23Dependent&&year>=2026);const nl=num(m.newLife),ol=num(m.oldLife),np=num(m.newPension),op=num(m.oldPension),med=num(m.medical);const oldCalc=lifeDeduction(ol,'old',year);const newCalc=lifeDeduction(nl,'newLife',year,under23);const general=ol>60000?(under23&&year>=2026?Math.min(60000,oldCalc):Math.min(50000,oldCalc)):Math.min(under23&&year>=2026?60000:40000,newCalc+oldCalc);const pension=op>60000?lifeDeduction(op,'old',year):Math.min(40000,lifeDeduction(np,'new',year)+lifeDeduction(op,'old',year));const medical=Math.min(40000,lifeDeduction(med,'new',year));const total=Math.min(120000,general+pension+medical);return{general,pension,medical,total,raw:{newLife:nl,oldLife:ol,medical:med,newPension:np,oldPension:op}}}
function earthquakeDeduction(m){const e=num(m.earthquake),old=num(m.oldLongTermDamage);return Math.min(50000,e)+Math.min(15000,old)}
const MANUAL_BASIS_KEYS=['temporary','life','earthquake','ideco','nationalPension','daughterNationalPension','dependents','adjustment'];
function defaultManual(){return {newLife:0,oldLife:0,medical:0,newPension:0,oldPension:0,earthquake:0,oldLongTermDamage:0,ideco:0,nationalPension:0,daughterNationalPension:0,daughterPensionEligible:true,temporary:0,temporaryTaxable:true,under23Dependent:false,adjustmentSpecialDisabled:false,dependentsGeneral:0,dependentsSpecific:0,dependentsElderly:0,dependentsElderlyCohabiting:0,specialDependentCount:0,specialDependentIncome:0,basis:{temporary:{source:false,salary:true},life:{source:false,salary:true},earthquake:{source:false,salary:true},ideco:{source:false,salary:true},nationalPension:{source:false,salary:true},daughterNationalPension:{source:false,salary:true},dependents:{source:false,salary:true},adjustment:{source:false,salary:true}},note:''}}
function manualFor(year){const base=defaultManual(), saved=state.manual[String(year)]||{};const merged={...base,...saved,basis:{...base.basis}};for(const k of MANUAL_BASIS_KEYS){const b=saved.basis?.[k];if(b&&typeof b==='object'){merged.basis[k]={source:Boolean(b.source),salary:Boolean(b.salary)}}else if(typeof b==='string'){merged.basis[k]={source:b==='source',salary:b==='salary'}}}if(saved.useManual){for(const k of MANUAL_BASIS_KEYS){if(k==='temporary'||!Object.prototype.hasOwnProperty.call(saved.useManual,k))continue;const old=Boolean(saved.useManual[k]);if(!saved.basis?.[k])merged.basis[k]={source:!old,salary:old}}}return merged}
function sourceWithholding(docs,year){const rows=docs.filter(d=>d.kind==='withholding'&&Number(d.year)===Number(year)&&!d.needsReview);if(!rows.length)return null;return rows.slice().sort((a,b)=>Number(b.month||0)-Number(a.month||0))[0]}
function sourceLifeFromWithholding(w,year){if(w?.lifeInsuranceDeduction!=null)return num(w.lifeInsuranceDeduction);if([w?.newLifeInsurance,w?.oldLifeInsurance,w?.nursingMedicalInsurance,w?.newPersonalPensionInsurance,w?.oldPersonalPensionInsurance].some(v=>v!=null)){const m={newLife:num(w.newLifeInsurance),oldLife:num(w.oldLifeInsurance),medical:num(w.nursingMedicalInsurance),newPension:num(w.newPersonalPensionInsurance),oldPension:num(w.oldPersonalPensionInsurance),under23Dependent:false};return calcLife(m,year).total}return 0}
function sourceBasicFromWithholding(w,year,income){return w?.basicDeduction!=null?num(w.basicDeduction):basicDeduction(income,year)}
function sourceEarthFromWithholding(w){return num(w?.earthquakeInsuranceDeduction)+Math.min(15000,num(w?.oldLongTermDamageInsurance))}
function sourceDeductionResidual(w,year){if(!w||w.deductionsTotal==null)return 0;const social=num(w.socialInsurance??w.social), basic=sourceBasicFromWithholding(w,year,num(w.salaryIncomeAfterDeduction)), life=sourceLifeFromWithholding(w,year), earth=sourceEarthFromWithholding(w);return Math.max(0,num(w.deductionsTotal)-social-basic-life-earth)}
function sourceIdecoFromWithholding(w){return w?.ideco!=null?num(w.ideco):w?.smallBusinessMutualAid!=null?num(w.smallBusinessMutualAid):w?.socialInsuranceInner!=null?num(w.socialInsuranceInner):null}
function basisOn(m,key,side){return Boolean(m.basis?.[key]?.[side])}
function calcBasisSide(w,year,m,side,includeComparison=false){
 const salaryRef=forecastSalaryBonus(state.documents||[],year);
 const salaryBasePayment=salaryRef?salaryRef.yearSalary+salaryRef.bonusTotal:0;
 const sourceBasePayment=num(w?.paymentAmount??w?.annualSalary);
 const sourceIncomeOriginal=num(w?.salaryIncomeAfterDeduction);
 const sourceSocial=num(w?.socialInsurance??w?.social);
 const sourceLife=sourceLifeFromWithholding(w,year);
 const sourceEarth=sourceEarthFromWithholding(w);
 const sourceResidual=sourceDeductionResidual(w,year);
 const sourceDependent=Math.max(0,sourceResidual);
 const sourceIdeco=sourceIdecoFromWithholding(w);
 const salarySocial=salaryRef?salaryRef.totalSocial:0;
 const manualLife=calcLife(m,year).total, manualEarth=earthquakeDeduction(m), manualIdeco=num(m.ideco);
 const manualNat=num(m.nationalPension), manualDaughter=m.daughterPensionEligible?num(m.daughterNationalPension):0;
 const manualDependent=dependentDeduction(m,year);
 const manualTemporary=num(m.temporary);
 const tempOn=basisOn(m,'temporary',side), lifeOn=basisOn(m,'life',side), earthOn=basisOn(m,'earthquake',side), idecoOn=basisOn(m,'ideco',side), natOn=basisOn(m,'nationalPension',side), daughterOn=basisOn(m,'daughterNationalPension',side), depOn=basisOn(m,'dependents',side), adjOn=basisOn(m,'adjustment',side);
 const payment=(side==='source'?sourceBasePayment:salaryBasePayment)+(tempOn?manualTemporary:0);
 const social=(side==='source'?sourceSocial:salarySocial)+(natOn?manualNat:0)+(daughterOn?manualDaughter:0);
 const life=lifeOn?manualLife:(side==='source'?sourceLife:0);
 const earth=earthOn?manualEarth:(side==='source'?sourceEarth:0);
 const ideco=idecoOn?manualIdeco:(side==='source'?(sourceIdeco??0):0);
 const nat=natOn?manualNat:0;
 const daughter=daughterOn?manualDaughter:0;
 const dependent=depOn?manualDependent:(side==='source'?sourceDependent:0);
 const salaryDed=salaryDeduction(payment,year);
 const baseIncome=side==='source' ? (tempOn?Math.max(0,payment-salaryDed):sourceIncomeOriginal) : Math.max(0,payment-salaryDed);
 const sourceAdjustment=num(w?.incomeAdjustment??w?.incomeAdjustmentDeduction??0);
 const adjustment=adjOn?adjustmentDeduction(Math.max(0,payment-salaryDed),year,m):(side==='source'?sourceAdjustment:0);
 const income=Math.max(0,baseIncome-adjustment);
 const residentBasic=residentBasicDeduction(year,income);
 const residentTaxable=Math.max(0,Math.floor((income-social-nat-daughter-residentBasic-life-earth-ideco-dependent)/1000)*1000);
 const rate=incomeTaxRate(residentTaxable),cap=payment>0?Math.floor(2000+(residentTaxable*.10*.20)/(0.90-rate*1.021)):0;
 return {side,payment,social,life,earth,ideco,nat,daughter,dependent,adjustment,income,residentBasic,residentTaxable,rate,cap,sourcePayment:sourceBasePayment,sourceIncomeOriginal,sourceSocial,sourceLife,sourceEarth,sourceIdeco,sourceDependent,salaryPayment:salaryBasePayment,salarySocial,salaryLife:manualLife,salaryEarth:manualEarth,salaryIdeco:manualIdeco,salaryNat:manualNat,salaryDaughter:manualDaughter,salaryDependent:manualDependent,manualApplied:{temporary:tempOn,life:lifeOn,earthquake:earthOn,ideco:idecoOn,nationalPension:natOn,daughterNationalPension:daughterOn,dependents:depOn,adjustment:adjOn}};
}
function sourceReferenceCalculation(w,year,m,includeComparison=true){if(!w)return null;
 const sourceCalc=calcBasisSide(w,year,m,'source'),salaryCalc=calcBasisSide(w,year,m,'salary');
 const selectedSource=MANUAL_BASIS_KEYS.some(k=>basisOn(m,k,'source'));
 const selectedSalary=MANUAL_BASIS_KEYS.some(k=>basisOn(m,k,'salary'));
 const capSource=sourceCalc.cap,capSalary=salaryCalc.cap;
 const cap=selectedSource&&selectedSalary?null:(selectedSource?capSource:(selectedSalary?capSalary:0));
 return {source:w,sourcePayment:sourceCalc.sourcePayment,sourceIncomeOriginal:sourceCalc.sourceIncomeOriginal,sourceIncome:sourceCalc.income,sourceSocial:sourceCalc.sourceSocial,sourceLife:sourceCalc.sourceLife,sourceEarth:sourceCalc.sourceEarth,sourceDependent:sourceCalc.sourceDependent,sourceIdeco:sourceCalc.sourceIdeco,salaryPayment:salaryCalc.salaryPayment,salarySocial:salaryCalc.salarySocial,salaryLife:salaryCalc.salaryLife,salaryEarth:salaryCalc.salaryEarth,salaryIdeco:salaryCalc.salaryIdeco,salaryNat:salaryCalc.salaryNat,salaryDaughter:salaryCalc.salaryDaughter,salaryDependent:salaryCalc.salaryDependent,social:sourceCalc.social,capSource,capSalary,payment:sourceCalc.payment+salaryCalc.payment,life:sourceCalc.life,earth:sourceCalc.earth,manualIdeco:sourceCalc.ideco,manualNat:sourceCalc.nat,daughter:sourceCalc.daughter,grossWithManual:sourceCalc.payment,salaryDed:salaryCalc.salaryDed,dependent:sourceCalc.dependent,adjustment:sourceCalc.adjustment,residentBasic:sourceCalc.residentBasic,residentTaxable:sourceCalc.residentTaxable,rate:sourceCalc.rate,cap,adjustmentSource:sourceCalc.adjustment,adjustmentSalary:salaryCalc.adjustment,selectedBasis:{...m.basis},sourceCalc,salaryCalc,sourceEnabled:true,salaryEnabled:true,manualOverrides:MANUAL_BASIS_KEYS.filter(k=>basisOn(m,k,'source')||basisOn(m,k,'salary'))};
}
function salaryDeduction(gross,year){if(year>=2026){if(gross<=2200000)return 740000;if(gross<=3600000)return gross*.3+80000;if(gross<=6600000)return gross*.2+440000;if(gross<=8500000)return gross*.1+1100000;return 1950000}if(year===2025){if(gross<=1900000)return 650000;if(gross<=3600000)return gross*.3+80000;if(gross<=6600000)return gross*.2+440000;if(gross<=8500000)return gross*.1+1100000;return 1950000}if(gross<=1625000)return 550000;if(gross<=1800000)return gross*.4-100000;if(gross<=3600000)return gross*.3+80000;if(gross<=6600000)return gross*.2+440000;if(gross<=8500000)return gross*.1+1100000;return 1950000}
function basicDeduction(income,year){if(year<=2024){if(income<=23500000)return 480000;return income<=24000000?320000:income<=24500000?160000:0}if(year===2025){if(income<=1320000)return 950000;if(income<=3360000)return 880000;if(income<=4890000)return 680000;if(income<=6550000)return 630000;if(income<=23500000)return 580000;return income<=24000000?480000:income<=24500000?320000:income<=25000000?160000:0}if(income<=1320000)return 1040000;if(income<=3360000)return 880000;if(income<=4890000)return 680000;if(income<=6550000)return 630000;if(income<=23500000)return 620000;return income<=24000000?480000:income<=24500000?320000:income<=25000000?160000:0}
function dependentIncomeLimit(year){return year<=2024?480000:year===2025?580000:620000}
function dependentDeduction(m,year){const g=Math.max(0,Math.floor(num(m.dependentsGeneral)));const sp=Math.max(0,Math.floor(num(m.dependentsSpecific)));const e=Math.max(0,Math.floor(num(m.dependentsElderly)));const c=Math.max(0,Math.floor(num(m.dependentsElderlyCohabiting)));const elderlyNonCohab=Math.max(0,e-c);const specialCount=Math.max(0,Math.floor(num(m.specialDependentCount)));const specialIncome=num(m.specialDependentIncome);let special=0;if(year>=2025&&specialCount>0){const bands=year===2025?[[580000,850000,630000],[850000,900000,610000],[900000,950000,510000],[950000,1000000,410000],[1000000,1050000,310000],[1050000,1100000,210000],[1100000,1150000,110000],[1150000,1200000,60000],[1200000,1230000,30000]]:[[620000,850000,630000],[850000,900000,610000],[900000,950000,510000],[950000,1000000,410000],[1000000,1050000,310000],[1050000,1100000,210000],[1100000,1150000,110000],[1150000,1200000,60000],[1200000,1230000,30000]];const b=bands.find(([lo,hi])=>specialIncome>lo&&specialIncome<=hi);special=b?b[2]*specialCount:0}return g*380000+sp*630000+elderlyNonCohab*480000+c*580000+special}
function adjustmentDeduction(gross,year,m){if(gross<=8500000)return 0;if(!m.under23Dependent&&!m.adjustmentSpecialDisabled)return 0;return Math.ceil((Math.min(gross,10000000)-8500000)*0.1)}
function incomeTaxRate(t){if(t<=1949000)return .05;if(t<=3299000)return .10;if(t<=6949000)return .20;if(t<=8999000)return .23;if(t<=17999000)return .33;if(t<=39999000)return .40;return .45}
function forecastSalaryTaxable(docs,year){const sal=docs.filter(d=>d.kind==='salary'&&d.year===year&&!d.needsReview&&d.taxable!=null).sort((a,b)=>a.month-b.month);const by=new Map(sal.map(d=>[Number(d.month),d]));const est={};const actualValues=sal.map(d=>num(d.taxable));const aprSep=sal.filter(d=>d.month>=4&&d.month<=9).map(d=>num(d.taxable));const baseline=aprSep.length?aprSep:(actualValues.length?actualValues:[]);const avg=baseline.length?baseline.reduce((a,b)=>a+b,0)/baseline.length:0;for(let m=1;m<=12;m++){if(by.has(m)){est[m]={value:num(by.get(m).taxable),source:'actual'};continue}if(avg>0){est[m]={value:avg,source:'forecast',basis:baseline.length?'Apr-Sep actuals available':'available actuals'};}}return{sal,est,baselineAverage:avg,baselineMonths:aprSep.length?sal.filter(d=>d.month>=4&&d.month<=9).map(d=>d.month):sal.map(d=>d.month)}}
function bonusForecast(docs,year){const current=docs.filter(d=>d.kind==='bonus'&&d.year===year&&!d.needsReview);const actualMonths=new Set(current.map(d=>Number(d.month)||0));const actual=current.reduce((s,d)=>s+num(d.taxable??d.amount??d.bonusAmount??d.totalPayment),0);const prior=docs.filter(d=>d.kind==='bonus'&&d.year===year-1&&!d.needsReview);const forecasts=[];for(const d of prior){const m=Number(d.month)||0;if(!m||actualMonths.has(m))continue;const amount=num(d.taxable??d.amount??d.bonusAmount??d.totalPayment);if(amount>0)forecasts.push({month:m,value:amount,sourceYear:year-1,social:num(d.social)});}const forecast=forecasts.reduce((s,x)=>s+x.value,0);const forecastSocial=forecasts.reduce((s,x)=>s+x.social,0);return{bs:current,actual,winter:current.find(d=>Number(d.month)===12),prior,forecast,forecastSocial,forecasts,source:forecasts.length?'prior-year':'actual-only'}}
function residentSalaryDeduction(gross,year){return salaryDeduction(gross,year)}
function residentBasicDeduction(year,income){return income<=24000000?430000:income<=24500000?290000:income<=25000000?150000:0}
function residentDependentDeduction(m,year){const g=Math.max(0,Math.floor(num(m.dependentsGeneral)));const sp=Math.max(0,Math.floor(num(m.dependentsSpecific)));const e=Math.max(0,Math.floor(num(m.dependentsElderly)));const c=Math.max(0,Math.floor(num(m.dependentsElderlyCohabiting)));const elderlyNon=Math.max(0,e-c);const specialCount=Math.max(0,Math.floor(num(m.specialDependentCount)));const income=num(m.specialDependentIncome);let special=0;if(year>=2025&&specialCount>0){const bands=[[580000,950000,450000],[950000,1000000,410000],[1000000,1050000,310000],[1050000,1100000,210000],[1100000,1150000,110000],[1150000,1200000,60000],[1200000,1230000,30000]];const b=bands.find(([lo,hi])=>income>lo&&income<=hi);special=b?b[2]*specialCount:0}return g*330000+sp*450000+elderlyNon*380000+c*450000+special}
